package com.drivique.api.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="payment_receipts",schema="billing") public class PaymentReceipt { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="payment_id",nullable=false,unique=true) private Payment payment; @Column(name="receipt_number",nullable=false,unique=true,length=50) private String receiptNumber; @Column(name="pdf_url",nullable=false,length=1000) private String pdfUrl; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); protected PaymentReceipt(){} public PaymentReceipt(Payment payment,String receiptNumber,String pdfUrl){this.payment=payment;this.receiptNumber=receiptNumber;this.pdfUrl=pdfUrl;} public UUID getId(){return id;} public Payment getPayment(){return payment;} public String getReceiptNumber(){return receiptNumber;} public String getPdfUrl(){return pdfUrl;} }
